local index = {}
for i = 1, #ALPHA do
  local c = ALPHA:sub(i, i)
  index[c], index["~" .. c], index["^" .. c] = i, #ALPHA + i, 2 * #ALPHA + i
end
local blocks = {}
for y, layer in ipairs(LAYERS) do
  local cell = 0
  for count, sym in layer:gmatch("(%d*)([~%^]?[^%d~%^])") do
    local n = tonumber(count) or 1
    local block = PALETTE[index[sym]]
    if block and not block:find(":") then block = "minecraft:" .. block end
    for i = cell, cell + n - 1 do
      if block then blocks[#blocks + 1] = { i % W, y - 1, math.floor(i / W), block } end
    end
    cell = cell + n
  end
end
return { name = "Pagoda", blocks = blocks }
